padre = {
    "Salomón": "David",
    "Roboam": "Salomón",
    "Abías": "Roboam",
    "Asa": "Abías",
    "Josafat": "Asa",
    "Joram": "Josafat",
    "Uzías": "Joram",
    "Jotam": "Uzías",
    "Acaz": "Jotam",
    "Ezequías": "Acaz",
    "Manasés": "Ezequías",
    "Amón": "Manasés",
    "Josías": "Amón",
}

def ascendencia(nombre):
    if nombre not in padre:
        return [nombre]
    return [nombre] + ascendencia(padre[nombre])

def ascendencia_iter(nombre):
    return ascendencia(nombre)

print(ascendencia_iter("Josías") == ascendencia("Josías"))
